"""LaTeX output: the macro file and booktabs tables.

Macro values arrive already formatted by the analysis that computed them, so nothing
here rounds or reformats a number. Table cells are the exception: a table is a view of
raw values, so its columns carry the format.
"""

from __future__ import annotations

import re
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

from hidden_options.publish.results import Result

_MACRO_NAME = re.compile(r"[A-Za-z]+")
MACROS_HEADER = (
    "% Generated by `hidden-options publish` from results/*.json. Do not edit by hand.\n"
)
MISSING_CELL = "--"


def collect_macros(results: Mapping[str, Result]) -> dict[str, str]:
    """Merge every result's macros into one name -> value map, sorted by name.

    LaTeX macro names are letters only, so anything else (digits, underscores) would
    either fail to compile or silently end the name early. A name defined by two
    results would make one of them win, so that is an error too, as is a value that
    could close its own braces or break the line.
    """
    merged: dict[str, str] = {}
    owner: dict[str, str] = {}
    for result_name, result in results.items():
        for macro, value in result.macros.items():
            if not _MACRO_NAME.fullmatch(macro):
                raise ValueError(
                    f"Invalid macro name {macro!r} in result {result_name!r}: letters only"
                )
            if macro in merged:
                raise ValueError(
                    f"Macro {macro!r} is defined by both {owner[macro]!r} and {result_name!r}"
                )
            _check_value(macro, value)
            merged[macro] = value
            owner[macro] = result_name
    return dict(sorted(merged.items()))


def _check_value(macro: str, value: object) -> None:
    if not isinstance(value, str) or "\n" in value:
        raise ValueError(f"Macro {macro!r} must be a single-line string, got {value!r}")
    depth = 0
    for char in value:
        depth += (char == "{") - (char == "}")
        if depth < 0:
            break
    if depth != 0:
        raise ValueError(f"Macro {macro!r} has unbalanced braces: {value!r}")


def render_macros(results: Mapping[str, Result]) -> str:
    """The text of `paper/numbers.tex`: one `\\newcommand` per macro, sorted by name.

    `\\newcommand` rather than `\\renewcommand` so a name that collides with something
    LaTeX or a package already defines stops the build instead of replacing it.
    """
    lines = [
        f"\\newcommand{{\\{name}}}{{{value}}}\n" for name, value in collect_macros(results).items()
    ]
    return MACROS_HEADER + "".join(lines)


@dataclass(frozen=True)
class Column:
    """One table column.

    `key` selects the value from each row. `fmt` is either a format spec (`.5f`,
    `,.0f`) or a full format string with one field (`${:+.2f}$`, `{:.1f}\\%`), the
    latter for cells that need math mode or a unit. `align` is the tabular column
    specifier.
    """

    key: str
    header: str
    fmt: str
    align: str = "r"


def render_table(
    rows: Sequence[Mapping[str, Any]],
    columns: Sequence[Column],
    *,
    caption: str,
    label: str,
    notes: str | None = None,
) -> str:
    """A booktabs `table` environment.

    Headers, caption and notes are LaTeX as written. A missing value (None) prints as
    a dash. A row without the column's key raises KeyError, so a spec that drifts from
    its result fails loudly instead of printing a blank cell.
    """
    if not columns:
        raise ValueError("A table needs at least one column")

    head = " & ".join(column.header for column in columns)
    body = [" & ".join(_cell(row, column) for column in columns) + " \\\\" for row in rows]
    lines = [
        "\\begin{table}[t]",
        "\\centering",
        f"\\caption{{{caption}}}",
        f"\\label{{{label}}}",
        f"\\begin{{tabular}}{{{''.join(column.align for column in columns)}}}",
        "\\toprule",
        f"{head} \\\\",
        "\\midrule",
        *body,
        "\\bottomrule",
        "\\end{tabular}",
    ]
    if notes is not None:
        lines.append(f"\\par\\smallskip{{\\footnotesize {notes}\\par}}")
    lines.append("\\end{table}")
    return "\n".join(lines) + "\n"


def _cell(row: Mapping[str, Any], column: Column) -> str:
    try:
        value = row[column.key]
    except KeyError:
        raise KeyError(f"Row has no value for column {column.key!r}") from None
    if value is None:
        return MISSING_CELL
    if "{" in column.fmt:
        return column.fmt.format(value)
    return format(value, column.fmt)
